/// <summary>
/// Price check (HSMobileOpsPriceCheckSvc/checkPrice): one item, variant, quantity and unit, priced for the warehouse's store.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPriceCheckRequest
{
    DataAreaId       dataAreaId;
    str              warehouseId;
    str              itemId;
    str              configId;
    str              sizeId;
    str              colorId;
    str              styleId;
    real             quantity;
    str              unitId;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('ItemId')]
public str parmItemId(str _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('ConfigId')]
public str parmConfigId(str _value = configId)
{
    configId = _value;
    return configId;
}

[DataMemberAttribute('SizeId')]
public str parmSizeId(str _value = sizeId)
{
    sizeId = _value;
    return sizeId;
}

[DataMemberAttribute('ColorId')]
public str parmColorId(str _value = colorId)
{
    colorId = _value;
    return colorId;
}

[DataMemberAttribute('StyleId')]
public str parmStyleId(str _value = styleId)
{
    styleId = _value;
    return styleId;
}

[DataMemberAttribute('Quantity')]
public real parmQuantity(real _value = quantity)
{
    quantity = _value;
    return quantity;
}

[DataMemberAttribute('UnitId')]
public str parmUnitId(str _value = unitId)
{
    unitId = _value;
    return unitId;
}
